    public static func ==(lhs: BridgeFraming, rhs: BridgeFraming) -> Bool {
        if lhs.panX != rhs.panX {
            return false
        }
        if lhs.panY != rhs.panY {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(panX)
        hasher.combine(panY)
    }
}


